import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8IeflXD.js";var i=JSON.parse(`{"title":"No layout algorithm","description":"","frontmatter":{},"headers":[],"relativePath":"why-no-solver.md","filePath":"pages/why-no-solver.md"}`),a={name:`why-no-solver.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="no-layout-algorithm" tabindex="-1">No layout algorithm <a class="header-anchor" href="#no-layout-algorithm" aria-label="Permalink to “No layout algorithm”">​</a></h1><p>The package computes no pixel widths. It emits one track list and the browser distributes, which is both smaller and faster than the solver it replaced.</p><h2 id="what-was-deleted" tabindex="-1">What was deleted <a class="header-anchor" href="#what-was-deleted" aria-label="Permalink to “What was deleted”">​</a></h2><p>A width solver resolved declared width, minimum, maximum, and flex into pixels against the viewport width, on every derivation. It is gone.</p><h2 id="what-replaced-it" tabindex="-1">What replaced it <a class="header-anchor" href="#what-replaced-it" aria-label="Permalink to “What replaced it”">​</a></h2><p><code>trackList</code> in <code>src/4_slice.ts</code> emits one <code>grid-template-columns</code> value using <code>fr</code> and <code>minmax()</code>, written to a custom property by <code>src/9_css.ts</code>. The layout engine does the division.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grid-template-columns: minmax(80px, 220px) 2fr 1fr</span></span></code></pre></div><h2 id="the-measurement-that-motivated-it" tabindex="-1">The measurement that motivated it <a class="header-anchor" href="#the-measurement-that-motivated-it" aria-label="Permalink to “The measurement that motivated it”">​</a></h2><p>A resize drag writes the column width once per pointer move, and each write used to re-sort the whole row pipeline. After the fix, one width write at a hundred thousand rows costs 0.0126 ms, with the method and the machine recorded in <code>bench/README.md</code>.</p><p>Two causes sat behind that, both in the signals library rather than in this package: a nested-path write woke every other branch&#39;s subscriber, and the selector had no shallow comparison. Both are fixed there, which is why <code>g.state.colWidth.name.$(300)</code> now touches one column.</p><h2 id="what-it-costs" tabindex="-1">What it costs <a class="header-anchor" href="#what-it-costs" aria-label="Permalink to “What it costs”">​</a></h2><p>Nothing in the package can know what a flex column ends up occupying without measuring the document.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g.view.widths.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// the declared width</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">element.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBoundingClientRect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()   </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// the painted one</span></span></code></pre></div><p><code>view.widths</code> reports declared widths and says so in its own comment. A caller wanting the painted width reads the element, which is the honest answer rather than a second solver that would have to agree with the browser.</p><h2 id="why-this-is-the-right-trade" tabindex="-1">Why this is the right trade <a class="header-anchor" href="#why-this-is-the-right-trade" aria-label="Permalink to “Why this is the right trade”">​</a></h2><table tabindex="0"><thead><tr><th>a solver in the package</th><th>the track list</th></tr></thead><tbody><tr><td>duplicates the layout engine&#39;s arithmetic, and has to keep agreeing with it</td><td>states the constraint once and lets the engine answer</td></tr><tr><td>runs inside the reactive chain, so a drag re-derives it per pointer move</td><td>runs in layout, off the reactive chain entirely</td></tr><tr><td>owns rounding, sub-pixel, and overflow behaviour</td><td>inherits whatever the platform does</td></tr><tr><td>reports a number that may disagree with the paint</td><td>reports the declaration, and points at the element for the paint</td></tr></tbody></table><h2 id="row-heights-are-the-mirror-case" tabindex="-1">Row heights are the mirror case <a class="header-anchor" href="#row-heights-are-the-mirror-case" aria-label="Permalink to “Row heights are the mirror case”">​</a></h2><p>A row height is a declaration too, and the sizer turns declarations into offsets rather than measuring. Content whose height cannot be declared goes through <code>src/14_measure.ts</code>, which holds one resize observer per store, an estimate, a buffer zone, and scroll anchoring. See <a href="/hafley-rxjs/signal-grid/rows-height">Height</a>.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};